/* Prism · Terra Index — 设计令牌与布局（compact / web desktop / P-22 Signal over Chrome） */
:root {
  --bg: #0e1319;
  --panel: #151c26;
  --panel-2: #1a2330;
  --panel-3: #212c3c;
  --border: #273245;
  --border-soft: #1f2937;
  --text: #e8eef6;
  --muted: #9aa8bc;
  --faint: #64748b;
  --accent: #4da3ff;
  --accent-deep: #2563a8;
  --accent-soft: rgba(77, 163, 255, 0.13);
  --amber: #f2b23e;
  --amber-soft: rgba(242, 178, 62, 0.16);
  --green: #43d17c;
  --red: #ff7a7a;
  --violet: #b18cff;
  --radius: 8px;
  --radius-sm: 5px;
  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: var(--font);
  font-size: 13px;
  color: var(--text);
  background: var(--bg);
  display: grid;
  grid-template-rows: 52px minmax(0, 1fr) 46px;
  height: 100vh;
  overflow: hidden;
  font-variant-numeric: tabular-nums;
}

button { font-family: inherit; color: inherit; background: none; border: none; cursor: pointer; }
button:disabled { opacity: 0.38; cursor: default; }
:focus-visible { outline: 2px solid #7db8ff; outline-offset: 1px; border-radius: 3px; }

/* ---------- 顶栏 ---------- */
.topbar {
  display: flex; align-items: center; gap: 18px;
  padding: 0 16px;
  background: linear-gradient(180deg, #161f2b, #121924);
  border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: baseline; gap: 8px; }
.brand-mark {
  width: 14px; height: 14px; border-radius: 3px; align-self: center;
  background: linear-gradient(135deg, var(--accent) 55%, var(--amber) 55%);
}
.brand-name { font-size: 16px; font-weight: 700; letter-spacing: 0.4px; }
.brand-sub { color: var(--muted); font-size: 12px; }
.dataset-meta { color: var(--faint); font-size: 12px; flex: 1; }
.topbar-actions { display: flex; align-items: center; gap: 8px; }
.kbd-hint {
  font-size: 11px; color: var(--faint); border: 1px solid var(--border);
  border-radius: 4px; padding: 2px 6px;
}

.btn {
  font-size: 12.5px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 5px 12px;
  transition: background 0.12s, border-color 0.12s;
}
.btn:hover:not(:disabled) { background: var(--panel-3); border-color: #34435c; }
.btn-danger-ghost { color: #f0a0a0; }
.btn-ghost { background: transparent; }
.btn-block { display: block; width: 100%; }
.btn-sm { font-size: 11.5px; padding: 3px 8px; }

/* ---------- 主区 ---------- */
.main {
  display: grid;
  grid-template-columns: 288px minmax(0, 1fr) 304px;
  min-height: 0;
}

.rail-head { display: flex; align-items: baseline; gap: 8px; padding: 10px 12px 8px; }
.rail-title { font-size: 13px; font-weight: 700; letter-spacing: 0.3px; }
.rail-sub { font-size: 11px; color: var(--faint); }
.rail-empty {
  color: var(--faint); font-size: 12px; line-height: 1.7;
  padding: 12px; border: 1px dashed var(--border); border-radius: var(--radius);
  margin: 4px 12px;
}
.rail-empty b { color: var(--muted); }

/* ---------- 探针栏 ---------- */
.probe-rail {
  background: var(--panel);
  border-right: 1px solid var(--border);
  display: flex; flex-direction: column; min-height: 0;
}
.proj-chip-box { padding: 0 12px 8px; }
.proj-chip {
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
  background: var(--accent-soft);
  border: 1px solid rgba(77, 163, 255, 0.35);
  border-radius: var(--radius-sm);
  padding: 6px 8px;
}
.proj-k { font-size: 11px; color: var(--accent); font-weight: 700; }
.proj-v { font-size: 12px; flex: 1; }
.proj-nav { display: flex; gap: 2px; }

.chip-list { flex: 1; overflow-y: auto; padding: 2px 12px 8px; display: flex; flex-direction: column; gap: 6px; }
.chip {
  display: flex; align-items: center; gap: 6px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 5px 6px 5px 8px;
  transition: opacity 0.15s, border-color 0.15s;
}
.chip:hover { border-color: #34435c; }
.chip.muted { opacity: 0.45; border-style: dashed; }
.chip-label { flex: 1; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.chip-label b { color: var(--accent); font-weight: 600; }
.chip-n { font-size: 10.5px; color: var(--faint); }

.badge {
  font-size: 10px; padding: 1px 5px; border-radius: 3px; font-weight: 600;
  white-space: nowrap;
}
.origin-chart   { color: #8cc2ff; background: rgba(77, 163, 255, 0.16); }
.origin-manual  { color: #7fe0a8; background: rgba(67, 209, 124, 0.14); }
.origin-history { color: #cdb4ff; background: rgba(177, 140, 255, 0.15); }
.origin-dim     { color: #f0cd88; background: rgba(242, 178, 62, 0.14); }
.origin-reset   { color: #ffa3a3; background: rgba(255, 122, 122, 0.14); }

.icon-btn {
  font-size: 12px; color: var(--muted);
  width: 20px; height: 20px; line-height: 18px; text-align: center;
  border-radius: 4px; flex: none;
}
