  --panel-2: #1a2330;
  --panel-3: #212c3c;
  --border: #273245;
  --border-soft: #1f2937;
  --text: #e8eef6;
  --muted: #9aa8bc;
  --faint: #64748b;
  --accent: #4da3ff;
  --accent-deep: #2563a8;
  --accent-soft: rgba(77, 163, 255, 0.13);
  --amber: #f2b23e;
  --amber-soft: rgba(242, 178, 62, 0.16);
  --green: #43d17c;
  --red: #ff7a7a;
  --violet: #b18cff;
  --radius: 8px;
  --radius-sm: 5px;
  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: var(--font);
