88	  function applyProbes(rows) {
89	    var byDim = {};
90	    activeProbes().forEach(function (p) { (byDim[p.dim] = byDim[p.dim] || []).push(String(p.value)); });
91	    return rows.filter(function (r) {
92	      for (var dim in byDim) {
93	        if (byDim[dim].indexOf(String(r[dim])) === -1) return false;
94	      }
95	      return true;
96	    });
97	  }
