99	  function aggregate(rows, key, agg) {
100	    if (!rows.length) return NaN;
101	    var vs = rows.map(function (r) { return r[key]; });
102	    if (agg === 'sum') return vs.reduce(function (a, b) { return a + b; }, 0);
103	    if (agg === 'median') {
104	      vs.sort(function (a, b) { return a - b; });
105	      var m = vs.length >> 1;
106	      return vs.length % 2 ? vs[m] : (vs[m - 1] + vs[m]) / 2;
107	    }
108	    return vs.reduce(function (a, b) { return a + b; }, 0) / vs.length;
109	  }
