111	  function project(rows) {
112	    var pj = state.projection, dim = pj.dim;
113	    var seen = {}, keys = [];
114	    rows.forEach(function (r) {
115	      var k = String(r[dim]);
116	      if (!seen[k]) { seen[k] = true; keys.push(k); }
117	    });
118	    var bars = keys.map(function (k) {
119	      var sub = rows.filter(function (r) { return String(r[dim]) === k; });
120	      return {
121	        key: k,
122	        value: aggregate(sub, pj.measure, pj.agg),
123	        n: sub.length,
124	        selN: sub.reduce(function (a, r) { return a + (state.selection.indexOf(r.id) !== -1 ? 1 : 0); }, 0)
125	      };
126	    });
127	    var s = pj.sort;
128	    if (s === 'value-desc') bars.sort(function (a, b) { return b.value - a.value; });
129	    else if (s === 'value-asc') bars.sort(function (a, b) { return a.value - b.value; });
130	    else if (s === 'name-asc') bars.sort(function (a, b) { return a.key.localeCompare(b.key, 'zh'); });
131	    else bars.sort(function (a, b) { return b.key.localeCompare(a.key, 'zh'); });
132	    return bars;
133	  }
