360	    }).join('');
361	    $('historyNodes').innerHTML = nodes;
362	    $('historyNodes').scrollLeft = 99999;
363	    $('historyNodes').querySelectorAll('.h-node').forEach(function (n) {
364	      n.onclick = function () { goTo(parseInt(n.getAttribute('data-i'), 10)); };
365	    });
366	    $('undoBtn').disabled = ptr === 0;
367	    $('redoBtn').disabled = ptr >= timeline.length - 1;
368	  }
369	
370	  function renderStatus() {
371	    var rows = applyProbes(T.records);
372	    var muted = state.probes.filter(function (p) { return p.muted; }).length;
373	    $('statusLine').innerHTML =
374	      '<span>镜头内 <b>' + rows.length + '</b> / ' + T.records.length + ' 条</span>' +
375	      '<span>探针 <b>' + state.probes.length + '</b>' + (muted ? '（' + muted + ' 静默）' : '') + '</span>' +
376	      '<span>选中 <b>' + state.selection.length + '</b></span>' +
377	      '<span>历史深度 <b>' + timeline.length + '</b></span>' +
378	      '<span class="status-keep">✓ 维度切换保留以上全部状态</span>';
379	  }
380	
381	  /* ---------- 动作 ---------- */
382	  function hasProbe(dim, value) {
383	    return state.probes.some(function (p) { return p.dim === dim && String(p.value) === String(value); });
384	  }
385	
386	  function toggleProbe(dim, value, origin) {
387	    var idx = state.probes.findIndex(function (p) { return p.dim === dim && String(p.value) === String(value); });
388	    var dimLabel = DIMS[dim].label;
389	    if (idx >= 0) {
390	      state.probes.splice(idx, 1);
391	      commit('移除探针 ' + dimLabel + '=' + value, 'probe');
392	      toast('已移除探针：' + dimLabel + ' = ' + value, 'remove');
393	    } else {
394	      state.probes.push({ id: 'p' + (++probeSeq), dim: dim, value: String(value), origin: origin, muted: false });
395	      commit('探针 ' + dimLabel + '=' + value, 'probe');
396	      toast('已添加探针：' + dimLabel + ' = ' + value + '（来源：' + (ORIGINS[origin] || {}).label + '）', 'add');
397	    }
398	    renderAll();
399	  }
400	
401	  function removeProbe(i) { var p = state.probes[i]; state.probes.splice(i, 1); commit('移除探针 ' + DIMS[p.dim].label + '=' + p.value, 'probe'); renderAll(); }
402	  function toggleMute(i) { var p = state.probes[i]; p.muted = !p.muted; commit((p.muted ? '静默' : '启用') + '探针 ' + DIMS[p.dim].label + '=' + p.value, 'probe'); renderAll(); }
403	  function clearProbes() {
404	    if (!state.probes.length) return;
405	    state.probes = []; commit('清空全部探针', 'probe'); renderAll(); toast('已清空全部探针', 'remove');
406	  }
407	
408	  function setProjection(next, label, origin) {
409	    var dimChanged = next.dim !== state.projection.dim;
410	    state.projection = clone(next);
411	    commit(label, 'projection');
412	    timeline[ptr].origin = origin;
413	    projStack = projStack.slice(0, projPtr + 1); projStack.push(clone(next)); projPtr++;
414	    renderAll();
415	    if (dimChanged) carryOver();
416	  }
417	
418	  function projectionStep(dir) {
419	    var np = projPtr + dir;
420	    if (np < 0 || np >= projStack.length) return;
421	    projPtr = np;
422	    state.projection = clone(projStack[np]);
423	    var wasDim = true;
424	    commit(dir < 0 ? '投影回退 → ' + DIMS[state.projection.dim].label : '投影前进 → ' + DIMS[state.projection.dim].label, 'projection');
425	    timeline[ptr].origin = dir < 0 ? 'projection-back' : 'projection-fwd';
426	    renderAll();
427	    if (wasDim) carryOver();
428	  }
429	
430	  function carryOver() {
431	    var el = $('carryOver');
432	    el.innerHTML = '投影维度 → <b>' + DIMS[state.projection.dim].label + '</b>' +
433	      ' · 保留 <b>' + state.probes.length + '</b> 探针 · <b>' + state.selection.length + '</b> 选中 · 排序 ' +
434	      ({ 'value-desc': '按值↓', 'value-asc': '按值↑', 'name-asc': '名称A→Z', 'name-desc': '名称Z→A' })[state.projection.sort];
435	    el.hidden = false;
436	    el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash');
437	    clearTimeout(carryTimer);
438	    carryTimer = setTimeout(function () { el.hidden = true; }, 5000);
439	  }
440	
441	  function toggleRecord(id) {
442	    var i = state.selection.indexOf(id);
443	    var r = T.records.find(function (x) { return x.id === id; });
444	    if (i >= 0) { state.selection.splice(i, 1); commit('取消选中 ' + r.country + ' ' + r.year, 'selection'); }
445	    else { state.selection.push(id); commit('选中 ' + r.country + ' ' + r.year, 'selection'); }
446	    renderAll();
447	  }
448	
449	  function clearSelection() {
450	    if (!state.selection.length) return;
451	    state.selection = []; commit('清除全部选择', 'selection'); renderAll();
452	  }
453	
454	  function resetAll() {
455	    state = initialState();
456	    commit('全部重置', 'reset');
457	    timeline[ptr].origin = 'reset';
458	    projStack = [clone(state.projection)]; projPtr = 0;
459	    renderAll(); toast('已回到初始状态（本次重置本身可撤销）', 'history');
460	  }
461	
462	  /* ---------- 表格排序（独立归属，跨投影保持） ---------- */
463	  var tableSort = { key: null, dir: 'desc' };
464	  function cycleTableSort(key) {
465	    if (tableSort.key !== key) tableSort = { key: key, dir: 'desc' };
466	    else if (tableSort.dir === 'desc') tableSort.dir = 'asc';
467	    else tableSort = { key: null, dir: 'desc' };
468	    commit(tableSort.key ? '排序：' + key + ' ' + tableSort.dir : '取消排序', 'sort');
469	    renderAll();
470	  }
471	
472	  /* ---------- Toast / 错误态 ---------- */
473	  function toast(msg, kind) {
474	    var t = document.createElement('div');
475	    t.className = 'toast toast-' + (kind || 'info');
476	    t.textContent = msg;
477	    $('toastStack').appendChild(t);
478	    setTimeout(function () { t.classList.add('out'); }, 2600);
479	    setTimeout(function () { t.remove(); }, 3000);
480	  }
481	  window.addEventListener('error', function (e) {
482	    toast('发生错误：' + (e.message || '未知'), 'error');
483	  });
484	
485	  /* ---------- 事件接线 ---------- */
486	  function wire() {
487	    $('dimSeg').addEventListener('click', function (e) {
488	      var b = e.target.closest('.seg-btn');
489	      if (!b || b.getAttribute('data-dim') === state.projection.dim) return;
490	      var next = clone(state.projection); next.dim = b.getAttribute('data-dim');
491	      setProjection(next, '投影维度 → ' + DIMS[next.dim].label, 'dimension');
492	    });
493	    $('measureSel').addEventListener('change', function (e) {
494	      var next = clone(state.projection); next.measure = e.target.value;
495	      setProjection(next, '度量 → ' + MEASURES[next.measure].label, 'measure');
496	    });
497	    $('aggSel').addEventListener('change', function (e) {
498	      var next = clone(state.projection); next.agg = e.target.value;
499	      setProjection(next, '聚合 → ' + e.target.options[e.target.selectedIndex].text, 'agg');
500	    });
501	    $('sortSel').addEventListener('change', function (e) {
502	      var next = clone(state.projection); next.sort = e.target.value;
503	      setProjection(next, '排序 → ' + e.target.options[e.target.selectedIndex].text, 'sort');
504	    });
505	
506	    $('probeList').addEventListener('click', function (e) {
507	      var btn = e.target.closest('.icon-btn'); if (!btn) return;
508	      var i = parseInt(btn.closest('.chip').getAttribute('data-i'), 10);
509	      if (btn.getAttribute('data-act') === 'rm') removeProbe(i); else toggleMute(i);
510	    });
511	
512	    $('inspectorBody').addEventListener('click', function (e) { /* 由卡片内按钮接管 */ });
513	    $('clearSelection').onclick = clearSelection;
514	    $('emptyClear').onclick = clearProbes;
515	    $('clearProbes').onclick = clearProbes;
516	    $('resetBtn').onclick = resetAll;
517	    $('undoBtn').onclick = undo;
518	    $('redoBtn').onclick = redo;
519	
520	    // 手动探针构建器
521	    var dimSel = $('manualDim');
522	    dimSel.innerHTML = Object.keys(DIMS).map(function (d) { return '<option value="' + d + '">' + DIMS[d].label + '</option>'; }).join('');
523	    dimSel.onchange = fillManualValues;
524	    function fillManualValues() {
525	      var vals = DIMS[dimSel.value].values;
526	      $('manualValue').innerHTML = vals.map(function (v) { return '<option value="' + esc(v) + '">' + esc(v) + '</option>'; }).join('');
527	    }
528	    fillManualValues();
529	    $('manualAdd').onclick = function () {
530	      var dim = dimSel.value, value = $('manualValue').value;
531	      if (hasProbe(dim, value)) { toast('该探针已存在：' + DIMS[dim].label + ' = ' + value, 'info'); return; }
532	      state.probes.push({ id: 'p' + (++probeSeq), dim: dim, value: String(value), origin: 'manual', muted: false });
533	      commit('探针 ' + DIMS[dim].label + '=' + value + '（手动）', 'probe');
534	      renderAll();
535	      toast('已添加探针：' + DIMS[dim].label + ' = ' + value + '（来源：手动）', 'add');
536	    };
537	
538	    // 键盘：undo/redo
539	    document.addEventListener('keydown', function (e) {
540	      if (!(e.ctrlKey || e.metaKey)) return;
541	      var k = e.key.toLowerCase();
542	      if (k === 'z' && !e.shiftKey) { e.preventDefault(); undo(); }
543	      else if (k === 'y' || (k === 'z' && e.shiftKey)) { e.preventDefault(); redo(); }
544	    });
545	
546	    window.addEventListener('resize', function () { renderChart(); });
547	  }
548	
549	  /* ---------- 启动：数据内联就绪，首屏直接渲染 ---------- */
550	  $('datasetMeta').textContent = T.records.length + ' 条观测 · ' + T.countries.length + ' 国 · ' + T.years[0] + '–' + T.years[T.years.length - 1] + ' · 数据内联就绪';
551	  wire();
552	  renderAll();
553	})();
