  background: var(--panel);
  border-right: 1px solid var(--border);
  display: flex; flex-direction: column; min-height: 0;
  overflow: hidden;
}
.proj-chip-box { padding: 0 12px 8px; }
.proj-chip {
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
  background: var(--accent-soft);
  border: 1px solid rgba(77, 163, 255, 0.35);
  border-radius: var(--radius-sm);
  padding: 6px 8px;
}
.proj-k { font-size: 11px; color: var(--accent); font-weight: 700; }
.proj-v { font-size: 12px; flex: 1; }
.proj-nav { display: flex; gap: 2px; }

.chip-list { flex: 1; overflow-y: auto; padding: 2px 12px 8px; display: flex; flex-direction: column; gap: 6px; }
.chip {
  display: flex; align-items: center; gap: 6px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 5px 6px 5px 8px;
  transition: border-color 0.15s;
}
.chip:hover { border-color: #34435c; }
.chip.muted { border-style: dashed; background: transparent; }
.chip.muted .chip-label { color: var(--muted); }
.chip.muted .chip-n { color: var(--disabled); }
.chip-label { flex: 1; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text); }
