:root {
  --bg: #0e1319;
  --panel: #151c26;
  --panel-2: #1a2330;
  --panel-3: #212c3c;
  --border: #273245;
  --border-soft: #1f2937;
  --text: #e8eef6;
  --muted: #9aa8bc;
  --faint: #8fa0b5;
  --disabled: #98a9bf;
  --accent: #4da3ff;
  --accent-deep: #2563a8;
  --accent-bg: #1c2d42;      /* accent-soft 的实色合成 */
  --amber: #f2b23e;
  --amber-bg: #3a3220;       /* amber-soft 的实色合成 */
  --green: #43d17c;
  --red: #ff7a7a;
  --violet: #b18cff;
  --radius: 8px;
  --radius-sm: 5px;
  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
