  background: linear-gradient(135deg, var(--accent) 55%, var(--amber) 55%);
}
.brand-name { font-size: 16px; font-weight: 700; letter-spacing: 0.4px; }
.brand-sub { color: var(--muted); font-size: 12px; }
.dataset-meta {
  color: var(--faint); font-size: 12px; flex: 1; min-width: 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.topbar-actions { display: flex; align-items: center; gap: 8px; flex: none; }
.kbd-hint {
  font-size: 11px; color: var(--faint); border: 1px solid var(--border);
