  var totalW = Math.max(cw, bars.length * minW + padL + padR);
  var slot = (totalW - padL - padR) / bars.length;
  var barW = Math.min(Math.max(slot - 10, 8), 64);
  var maxV = Math.max.apply(null, bars.map(function (b) { return b.value; }).concat([0]));
  var fmt = MEASURES[pj.measure].fmt;
  var many = bars.length > 14;

  var svg = '<svg width="' + totalW + '" height="' + H + '" viewBox="0 0 ' + totalW + ' ' + H + '" role="img" aria-label="' +
    esc(DIMS[pj.dim].label + ' × ' + MEASURES[pj.measure].label + '（' + pj.agg + '）投影柱状图') + '">';

  for (var g = 0; g <= 4; g++) {
