    var y = padT + innerH - h;
    var light = 38 + 26 * (1 - i / Math.max(bars.length - 1, 1));
    var active = hasProbe(pj.dim, b.key);
    var selH = b.n ? Math.max(h * b.selN / b.n, b.selN ? 3 : 0) : 0;
    svg += '<g class="bar' + (active ? ' active' : '') + '" role="button" tabindex="-1" data-key="' + esc(b.key) +
      '" aria-label="' + esc(b.key + '：' + fmt(b.value) + '，' + b.n + ' 条记录，选中 ' + b.selN) + (active ? '，已过滤' : '') + '">' +
