    svg += '<g class="bar' + (active ? ' active' : '') + '" role="button" tabindex="-1" data-key="' + esc(b.key) +
      '" aria-label="' + esc(b.key + '：' + fmt(b.value) + '，' + b.n + ' 条记录，选中 ' + b.selN) + (active ? '，已过滤' : '') + '">' +
