      '<rect class="bar-rect" x="' + x + '" y="' + y + '" width="' + barW + '" height="' + h + '" rx="3" fill="hsl(212,64%,' + light.toFixed(0) + '%)"/>' +
      (selH > 0 ? '<rect class="bar-sel" x="' + x + '" y="' + y + '" width="' + barW + '" height="' + Math.min(selH, h) + '" rx="2"/>' : '') +
      (bars.length <= 24 ? '<text x="' + (x + barW / 2) + '" y="' + (y - 6) + '" class="bar-val" text-anchor="middle">' + esc(fmt(b.value)) + '</text>' : '') +
      '<text x="' + (x + barW / 2) + '" y="' + (padT + innerH + 14) + '" class="bar-key' + (many ? ' rotated' : '') + '" ' +
        (many ? 'transform="rotate(-52 ' + (x + barW / 2) + ' ' + (padT + innerH + 14) + ')" text-anchor="end"' : 'text-anchor="middle"') + '>' +
        esc(b.key) + '</text>' +
      '<text x="' + (x + barW / 2) + '" y="' + (padT + innerH + (many ? 34 : 28)) + '" class="bar-n" text-anchor="middle">n=' + b.n + (b.selN ? ' · ◆' + b.selN : '') + '</text>' +
      '<title>' + esc(b.key + '\n' + MEASURES[pj.measure].label + '（' + pj.agg + '）：' + fmt(b.value) +
        '\n记录数：' + b.n + '\n其中选中：' + b.selN + '\n点击：' + (active ? '移除' : '添加') + '探针') + '</title>' +
    '</g>';
  });

  svg += '</svg>';
  wrap.innerHTML = svg;
  // 键盘模式：容器单 Tab 停靠，←/→ 在柱间漫游（漫游处理统一在 wire() 委托，避免重复绑定）
  wrap.setAttribute('tabindex', '0');
  wrap.setAttribute('role', 'group');
  wrap.setAttribute('aria-label', DIMS[pj.dim].label + ' × ' + MEASURES[pj.measure].label + ' 投影柱状图：← → 切换柱，Enter 切换过滤');
  wrap.querySelectorAll('.bar').forEach(function (node) {
    node.addEventListener('click', function () { toggleProbe(state.projection.dim, node.getAttribute('data-key'), 'chart-click'); });
    node.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleProbe(state.projection.dim, node.getAttribute('data-key'), 'chart-click'); }
    });
  });
}

